from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.board = [
            line.strip().split()
            for line in board.splitlines()
            if line.strip()
        ]
        self.size = len(self.board)

    def get_winner(self):
        if self._has_connection("X"):
            return "X"
        if self._has_connection("O"):
            return "O"
        return ""

    def _has_connection(self, player):
        # X connects left edge (col 0) to right edge (col == row).
        # O connects top edge (row 0) to bottom edge (row == size - 1).
        if player == "X":
            start = {(r, 0) for r in range(self.size)}
            goal = lambda r, c: c == r
        else:
            start = {(0, c) for c in range(self.size)}
            goal = lambda r, c: r == self.size - 1

        visited = set()
        queue = deque()
        for cell in start:
            if self._is_player(cell, player):
                visited.add(cell)
                queue.append(cell)

        while queue:
            r, c = queue.popleft()
            if goal(r, c):
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in visited and self._is_player((nr, nc), player):
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def _is_player(self, cell, player):
        r, c = cell
        return 0 <= r < self.size and 0 <= c <= r and self.board[r][c] == player

    def _neighbors(self, r, c):
        # Hex grid: each row is shifted right by one cell.
        for nr, nc in ((r, c - 1), (r, c + 1),
                        (r - 1, c), (r - 1, c + 1),
                        (r + 1, c), (r + 1, c + 1)):
            if 0 <= nr < self.size and 0 <= nc <= nr:
                yield nr, nc

