from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.board = [
            line.strip().split()
            for line in board.splitlines()
            if line.strip()
        ]
        self.rows = len(self.board)
        self.cols = len(self.board[0]) if self.board else 0

    def get_winner(self):
        if self._has_connection("X"):
            return "X"
        if self._has_connection("O"):
            return "O"
        return ""

    def _has_connection(self, player):
        # X connects the left edge (col 0) to the right edge (col cols - 1).
        # O connects the top edge (row 0) to the bottom edge (row rows - 1).
        if player == "X":
            start = {(r, 0) for r in range(self.rows)}
            goal = lambda r, c: c == self.cols - 1
        else:
            start = {(0, c) for c in range(self.cols)}
            goal = lambda r, c: r == self.rows - 1

        visited = set()
        queue = deque()
        for cell in start:
            if self._is_player(cell, player):
                visited.add(cell)
                queue.append(cell)

        while queue:
            r, c = queue.popleft()
            if goal(r, c):
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in visited and self._is_player((nr, nc), player):
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def _is_player(self, cell, player):
        r, c = cell
        return (
            0 <= r < self.rows
            and 0 <= c < self.cols
            and self.board[r][c] == player
        )

    def _neighbors(self, r, c):
        # Hex grid: each row is shifted right by half a cell relative to the row above.
        for nr, nc in ((r, c - 1), (r, c + 1),
                        (r - 1, c), (r - 1, c + 1),
                        (r + 1, c - 1), (r + 1, c)):
            if 0 <= nr < self.rows and 0 <= nc < self.cols:
                yield nr, nc

